const o = $input.first().json;
const cfg = { warehouse_pincode: 'REPLACE_WAREHOUSE_PINCODE', decision_webhook: 'https://REPLACE-N8N-DOMAIN/webhook/order-risk-decision', store: 'Your Store',
  low_max: 34, high_min: 65, ai_weight: 0.4, prepaid_link: 'https://yourstore.example.com/pages/pay-online' };
const ship = o.shipping_address || {}, bill = o.billing_address || {};
const digits = s => String(s || '').replace(/\D/g, '');
let phone = digits(ship.phone || o.phone || o.customer?.phone).slice(-10);
const cod = (o.payment_gateway_names || []).some(g => /cod|cash/i.test(g)) || /pending/i.test(o.financial_status || '');
const hex = n => Array.from({ length: n }, () => Math.floor(Math.random() * 16).toString(16)).join('');
return [{ json: { cfg, risk_id: String(o.id), order_id: String(o.id), order_gid: o.admin_graphql_api_id || `gid://shopify/Order/${o.id}`,
  order_name: o.name, created_at: o.created_at, email: String(o.email || o.customer?.email || '').toLowerCase(), phone, phone_wa: phone ? '91' + phone : '',
  customer_name: ship.name || `${o.customer?.first_name || ''} ${o.customer?.last_name || ''}`.trim(), customer_orders: Number(o.customer?.orders_count) || 1,
  address1: ship.address1 || '', address2: ship.address2 || '', city: ship.city || '', state: ship.province || '', pincode: digits(ship.zip).slice(0, 6),
  bill_pincode: digits(bill.zip).slice(0, 6), payment: cod ? 'COD' : 'Prepaid', total: Number(o.total_price) || 0,
  items: (o.line_items || []).map(l => ({ title: l.title, qty: l.quantity, price: Number(l.price) })), max_qty: Math.max(0, ...(o.line_items || []).map(l => l.quantity || 0)),
  discount_codes: (o.discount_codes || []).map(d => d.code), note: o.note || '', browser_ip: o.browser_ip || '', token: hex(24) } }];

const o = $('Risk Config & Normalize').first().json;
const h = $('Read Customer History').first()?.json || {};
const pr = $('Read Pincode Risk').first()?.json || {};
const sv = $('Check Courier Serviceability').first()?.json || {};
const ip = $('Look Up Pincode (India Post)').first()?.json || {};
const pts = [], hard = [];
const add = (p, why) => { if (p) pts.push({ p, why }); };
// payment & value
add(o.payment === 'COD' ? 15 : -10, o.payment === 'COD' ? 'COD order' : 'prepaid');
add(o.total > 10000 ? 20 : o.total > 5000 ? 10 : 0, `order value ₹${o.total}`);
// history
const rto = Number(h.rto) || 0, ret = Number(h.returns) || 0, del = Number(h.delivered) || 0, can = Number(h.cancelled) || 0;
if (/yes|true/i.test(String(h.blacklisted || ''))) hard.push('blacklisted customer');
if (!h.phone && o.customer_orders <= 1) add(8, 'first-time customer');
if (del >= 2 && rto === 0) add(-15, `${del} delivered orders, 0 RTO`);
add(Math.min(45, rto * 15), rto ? `${rto} past RTO` : '');
add(del + ret > 0 && ret / Math.max(1, del) > 0.5 ? 10 : 0, 'high return ratio');
add(can >= 2 ? 8 : 0, `${can} cancellations`);
// pincode
const rr = Number(pr.rto_rate_pct) || 0;
add(rr > 30 ? 20 : rr > 20 ? 12 : rr > 10 ? 5 : 0, `pincode RTO ${rr}%`);
add(/red|high/i.test(pr.risk_zone || '') ? 10 : 0, 'red-zone pincode');
// courier
const couriers = sv.body?.data?.available_courier_companies || [];
const svOk = sv.statusCode === 200 && couriers.length > 0;
if (sv.statusCode && !svOk) hard.push('pincode not serviceable');
if (svOk && o.payment === 'COD' && !couriers.some(c => Number(c.cod) === 1)) hard.push('COD not available at pincode');
const etd = couriers.map(c => Number(c.estimated_delivery_days)).filter(Boolean).sort((a, b) => a - b)[0] || null;
// postal match
const po = Array.isArray(ip.body) ? ip.body[0] : null;
const offices = po?.Status === 'Success' ? po.PostOffice || [] : [];
const norm = s => String(s || '').toLowerCase().replace(/[^a-z]/g, '');
const cityOk = !offices.length || offices.some(p => [p.District, p.Block, p.Name, p.Division].some(x => norm(x) && (norm(o.city).includes(norm(x)) || norm(x).includes(norm(o.city)))));
const stateOk = !offices.length || offices.some(p => norm(p.State) === norm(o.state));
if (po && po.Status !== 'Success') add(20, 'pincode does not exist (India Post)');
add(!cityOk ? 10 : 0, 'city ≠ pincode district'); add(!stateOk ? 15 : 0, 'state ≠ pincode state');
// address text
const addr = `${o.address1} ${o.address2}`.trim();
const addrPen = [];
if (addr.length < 25) addrPen.push(['short address', 12]);
if (!/\d/.test(addr)) addrPen.push(['no house/flat number', 8]);
if (!/(near|opp|behind|beside|landmark|road|street|nagar|colony|sector|block|floor|apartment|apt|lane|marg|chowk)/i.test(addr)) addrPen.push(['no street/landmark words', 5]);
if (/(test|asdf|qwer|xxx|abc abc|na na|\b(.)\2{4,})/i.test(addr) || /^[^a-z]*$/i.test(addr)) { addrPen.push(['junk address', 25]); hard.push('junk address'); }
addrPen.forEach(([w, p]) => add(p, w));
const addressQuality = Math.max(0, 100 - addrPen.reduce((a, [, p]) => a + p, 0) * 2 - (!cityOk ? 15 : 0) - (!stateOk ? 20 : 0));
// contact & behaviour
if (!/^[6-9]\d{9}$/.test(o.phone)) { add(25, 'invalid phone'); hard.push('invalid phone'); }
add(/@(mailinator|tempmail|10minutemail|guerrillamail|yopmail|trashmail)\./i.test(o.email) ? 10 : 0, 'disposable email');
add(o.bill_pincode && o.bill_pincode !== o.pincode ? 5 : 0, 'billing ≠ shipping pincode');
add(o.max_qty >= 5 ? 8 : 0, `bulk quantity (${o.max_qty})`);
add(o.discount_codes.length && o.payment === 'COD' && o.total > 3000 ? 5 : 0, 'discount + high-value COD');
const hr = new Date(new Date(o.created_at).getTime() + 5.5 * 3600000).getUTCHours();
add(hr < 5 ? 3 : 0, 'placed 0–5 AM IST');
const rule = Math.max(0, Math.min(100, pts.reduce((a, x) => a + x.p, 0)));
return [{ json: { ...o, rule_score: rule, rule_reasons: pts.filter(x => x.why).map(x => `${x.p > 0 ? '+' : ''}${x.p} ${x.why}`), hard_flags: hard,
  address_quality: addressQuality, postal: offices[0] ? `${offices[0].District}, ${offices[0].State}` : 'unknown', city_ok: cityOk, state_ok: stateOk,
  serviceable: svOk, couriers: couriers.length, etd_days: etd, history: { delivered: del, rto, returns: ret, cancelled: can }, pincode_rto_pct: rr } }];

