You are an RTO/fraud risk analyst for Indian e-commerce (COD heavy). You get an order's signals and a rule-based score.
Judge the probability that this order will be refused, returned to origin or fraudulent. Look at patterns the rules may miss: an address that looks fake or incomplete for that city, mismatched names, suspicious notes, unusual baskets.
Return ONLY JSON: {"ai_score": number (0-100), "top_reasons": [string] (max 3, short), "address_fix_suggestion": string (what to ask the customer, or ""), "recommended_action": "ship"|"confirm_with_customer"|"manual_review"}

parameters.jsCode:
const s = $('Address Quality & Rule Score').first().json;
const ai = $input.first().json.message?.content || {};
const w = s.cfg.ai_weight;
const aiScore = Number.isFinite(Number(ai.ai_score)) ? Number(ai.ai_score) : s.rule_score;
let final = Math.round((1 - w) * s.rule_score + w * aiScore);
let tier = s.hard_flags.length || final >= s.cfg.high_min ? 'high' : final > s.cfg.low_max ? 'medium' : 'low';
if (tier === 'medium' && s.payment === 'Prepaid' && ai.recommended_action !== 'manual_review') tier = 'low';   // prepaid: low RTO exposure
return [{ json: { ...s, ai_score: aiScore, ai_reasons: ai.top_reasons || [], address_fix: ai.address_fix_suggestion || '', final_score: final, tier,
  status: tier === 'low' ? 'released' : tier === 'medium' ? 'awaiting_customer' : 'held_review',
  confirm_url: `${s.cfg.decision_webhook}?id=${s.risk_id}&t=${s.token}&a=customer_confirm`,
  cancel_url: `${s.cfg.decision_webhook}?id=${s.risk_id}&t=${s.token}&a=customer_cancel`,
  release_url: `${s.cfg.decision_webhook}?id=${s.risk_id}&t=${s.token}&a=release`,
  ops_cancel_url: `${s.cfg.decision_webhook}?id=${s.risk_id}&t=${s.token}&a=cancel`,
  prepaid_url: `${s.cfg.decision_webhook}?id=${s.risk_id}&t=${s.token}&a=prepaid` } }];

const b = $('Blend Score & Decide').first().json;
const fos = ($input.first().json.body?.data?.order?.fulfillmentOrders?.edges || []).map(e => e.node).filter(n => /OPEN|SCHEDULED/.test(n.status));
const note = `GuardOS ${b.tier.toUpperCase()} risk ${b.final_score}: ${[...b.hard_flags, ...b.ai_reasons].slice(0, 3).join('; ')}`.replace(/"/g, "'").slice(0, 250);
const holds = fos.map((f, i) => `h${i}: fulfillmentOrderHold(id: "${f.id}", fulfillmentHold: { reason: OTHER, reasonNotes: "${note}" }) { userErrors { message } }`).join(' ');
const tags = JSON.stringify(['risk-' + b.tier, 'risk-score-' + b.final_score, b.tier === 'medium' ? 'awaiting-confirmation' : 'risk-review']);
return [{ json: { fo_ids: fos.map(f => f.id).join(','), body: { query: `mutation { t: tagsAdd(id: "${b.order_gid}", tags: ${tags}) { userErrors { message } } ${holds} }` } } }];

