const q = $('On Decision Link Click').first().json.query || {};
const r = $input.first()?.json || {};
const a = String(q.a || '');
let reason = '';
if (!r.risk_id) reason = 'Order not found';
else if (!r.token || r.token === 'used' || r.token !== q.t) reason = 'This link was already used or is invalid';
else if (a.startsWith('customer_') && r.status !== 'awaiting_customer') reason = 'This order has already been processed';
else if (!['customer_confirm', 'customer_cancel', 'release', 'cancel', 'prepaid'].includes(a)) reason = 'Unknown action';
const fos = String(r.fo_ids || '').split(',').filter(Boolean);
const route = /confirm|release/.test(a) ? 'release' : /cancel/.test(a) ? 'cancel' : 'prepaid';
return [{ json: { ...r, act: a, route, valid: !reason, reason, by: a.startsWith('customer_') ? 'customer' : 'ops',
  release_body: { query: `mutation { t: tagsAdd(id: "${r.order_gid}", tags: ["risk-cleared"]) { userErrors { message } } ${fos.map((f, i) => `r${i}: fulfillmentOrderReleaseHold(id: "${f}") { userErrors { message } }`).join(' ')} }` },
  cancel_body: { query: 'mutation($id:ID!,$note:String){ orderCancel(orderId:$id, reason:' + (a === 'customer_cancel' ? 'CUSTOMER' : 'FRAUD') + ', refund:true, restock:true, notifyCustomer:true, staffNote:$note){ job{ id } orderCancelUserErrors{ message } } }',
    variables: { id: r.order_gid, note: `GuardOS: cancelled by ${a.startsWith('customer_') ? 'customer' : 'ops'} (risk ${r.final_score})` } } } }];

return $input.all().map(i => i.json).filter(r => r.risk_id && r.assessed_at).flatMap(r => {
  const h = (Date.now() - new Date(r.assessed_at).getTime()) / 3600000;
  if (h >= 24) return [{ json: { ...r, sla: 'escalate', age_h: Math.round(h) } }];
  if (h >= 4 && !r.reminded_at) return [{ json: { ...r, sla: 'remind', age_h: Math.round(h) } }];
  return [];
});
